import os

# 辅助函数：提取元组中的实际值（用于文件路径）
def get_input_value(val):
    """如果输入是元组，返回第一个元素；否则返回原值"""
    if isinstance(val, tuple) and len(val) > 0:
        return val[0]
    return val

# 辅助函数：将元组转换为拼接字符串（用于第二个参数）
def tuple_to_string(val):
    """将元组所有元素转为字符串并拼接成一行，非元组则直接转字符串"""
    if isinstance(val, tuple):
        return ' '.join(str(item) for item in val)
    return str(val)

# 获取文件路径并处理元组情况
file_path = get_input_value(inputs['In01'])
# 将第二个输入参数（元组）转为字符串
second_param_str = tuple_to_string(inputs['In02'])

# 检查是否为有效的文本文件
if isinstance(file_path, str) and os.path.isfile(file_path) and file_path.lower().endswith('.txt'):
    try:
        # 读取文件所有行
        with open(file_path, 'r', encoding='utf-8') as f:
            lines = f.readlines()

        # 写回文件（跳过第一行）
        with open(file_path, 'w', encoding='utf-8') as f:
            f.writelines(lines[1:])

        outputs[0] = f"成功：已删除文件 '{file_path}' 的第一行"

    except UnicodeDecodeError:
        outputs[0] = f"错误：文件 '{file_path}' 编码错误，请使用UTF-8编码"
    except PermissionError:
        outputs[0] = f"错误：没有权限修改文件 '{file_path}'"
    except Exception as e:
        outputs[0] = f"错误：文件操作失败 - {str(e)}"
else:
    outputs[0] = f"错误：'{file_path}' 不是有效的文本文件路径"

# 将转换后的字符串返回到第二个输出
outputs[1] = second_param_str
